	it('returns all five columns even when empty', () => {
		const columns = distributeToColumns([]);
		expect(columns).toHaveLength(5);
		expect(columns.map((c) => c.id)).toEqual([
			'backlog',
			'ready',
			'in_progress',
			'review',
			'done'
		]);
	});
});

describe('getStatusClasses', () => {
